/* Three throwaway arrangements: A inline, B contained, C centered. No persistence or network. */
const params=new URLSearchParams(location.search), initial=Number(params.get('case')||1);
let current=initial, variant=['A','B','C'].includes(params.get('variant'))?params.get('variant'):'A';
const paths={back:'m15 6-6 6 6 6',next:'m9 6 6 6-6 6',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M18 6 6 18',check:'m5 12 4 4L19 6',task:'M9 6h12M9 12h12M9 18h12M2 6l1 1 2-2M2 12l1 1 2-2M2 18l1 1 2-2',calendar:'M4 5h16v16H4zM4 10h16M8 3v4M16 3v4',archive:'M3 4h18v5H3zM5 9v12h14V9M9 13h6',trash:'M4 6h16M9 3h6M6 6l1 15h10l1-15M10 10v7M14 10v7',habit:'m3 12 4 4 8-8M10 16l3 3L23 9',flag:'M5 22V3M5 4h13l-3 5 3 5H5',repeat:'m17 2 4 4-4 4M21 6H7a4 4 0 0 0-4 4m4 12-4-4 4-4M3 18h14a4 4 0 0 0 4-4',chat:'M3 4h18v13H8l-5 4V4',type:'M3 3h8l10 10-8 8L3 11V3M7 7h.01',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M12 10v7M12 6h.01',filter:'M3 6h18M6 12h12M10 18h4',down:'m7 10 5 5 5-5',send:'M12 20V4m-7 7 7-7 7 7',wifi:'M2 7q10-8 20 0M5 11q7-6 14 0M8 15q4-3 8 0M12 19h.01',battery:'M7 5h10v16H7zM10 2h4',bars:'M4 20v-4M10 20V9M16 20V3'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cases={
1:['Battle Plan','Daily work','task','No open tasks','Add a task when you have something to work on. Your next steps will appear here.','New task','task'],
2:['Battle Plan','Daily work','task','Nothing in progress','Tasks you start appear here, so you can keep track of what’s underway.','View open tasks','open'],
3:['Battle Plan','Daily work','check','No completed tasks yet','Tasks you mark complete will appear here.','View open tasks','open'],
5:['Battle Plan','Daily work','archive','No archived tasks','Completed tasks you archive appear here. You can restore them to the board any time.','',''],
6:['Battle Plan','Daily work','trash','Trash is empty','Tasks you delete stay here for 30 days, so you have time to restore them.','',''],
7:['Habits','Routines and goals','habit','Build a habit from a routine','Track a recurring routine or one of its checklist items. Your weekly progress will appear here.','Create a routine','routine'],
8:['Habits','Routines and goals','habit','Create a routine first','Habits come from recurring routines and their checklist items. Create one, then choose what to track.','Create a routine','routine'],
9:['Recurring Tasks','Routines and goals','repeat','No active series','Create a Recurring Task Series for work that repeats on a schedule or quota.','New recurrence','routine'],
10:['Recurring Tasks','Routines and goals','repeat','No paused series','Series you pause appear here. Resume one when you’re ready to continue.','View active series','active'],
11:['Recurring Tasks','Routines and goals','archive','No ended series','Series you end appear here, keeping them separate from your active routines.','View active series','active'],
12:['Time Goals','Routines and goals','flag','No time goals this week','Choose a Task Type and a repeating time target. Your Actual Blocks supply the progress.','Add Time Goal','goal'],
15:['Conversation','','chat','What would help today?','Ask about your time, review your tasks, or plan your next step.','',''],
28:['Preferences','Settings','calendar','No calendars available','Sync again to check this account for calendars. If none appear, check the account in Google Calendar.','Sync calendars','sync'],
36:['Battle Plan','Daily work','type','No Task Types yet','Type a name above to create a category, such as study or work/design.','','']};
function report(action='Initial empty state'){parent.postMessage({type:'empty-prototype-state',id:initial,current,variant,action},'*')}
function button(text,action,primary=true){return `<button class="${primary?'primary':'text-action'}" data-action="${action}">${primary&&['task','routine','goal'].includes(action)?icon('plus'):''}${esc(text)}</button>`}
function stateBlock(id){const c=cases[id], primary=![2,3,10,11].includes(id);return `<section class="stage"><div class="empty-icon">${icon(c[2])}</div><div class="state-copy"><div class="context-line"><h2>${c[3]}</h2>${id===12?`<button aria-label="How time goals work" data-action="help">${icon('info')}</button>`:''}</div><p>${c[4]}</p></div>${c[5]?`<div class="actions">${button(c[5],c[6],primary)}</div>`:''}${id===12?'<div id="goal-help"></div>':''}</section>`}
function header(c){return `<header class="header ${current===15?'conversation':''}"><button class="back iconbutton" aria-label="Back" data-action="back">${icon('back')}</button><div>${c[1]?`<p class="group">${c[1].toUpperCase()}</p>`:''}<h1>${c[0]}</h1></div>${current===15?`<button class="iconbutton" aria-label="New conversation" data-action="reset">${icon('plus')}</button>`:''}</header>`}
function week(){return `<div class="week"><button aria-label="Previous week" data-action="historical">${icon('back')}</button><span>This week</span><button aria-label="Next week" disabled>${icon('next')}</button></div>`}
function dock(){return `<nav class="dock" aria-label="App shortcuts"><button data-action="day">${icon('calendar')}Day</button><button class="${[1,2,3,5,6,36].includes(current)?'selected':''}" data-action="board">${icon('task')}Battle Plan</button></nav><div class="home-line"></div>`}
function tabs(){return `<div class="tabs">${[[1,'Open'],[2,'In Progress'],[3,'Completed']].map(([n,label])=>`<button data-case="${n}" class="${current===n?'selected':''}">${label} &nbsp;0</button>`).join('')}</div>`}
function recurrenceTabs(){return `<div class="tabs">${[[9,'Active'],[10,'Paused'],[11,'Ended']].map(([n,label])=>`<button data-case="${n}" class="${current===n?'selected':''}">${label}</button>`).join('')}</div>`}
function conversation(){return `<div class="body conversation-body"><section class="stage"><div class="empty-icon">${icon('chat')}</div><div class="state-copy"><h2>${cases[15][3]}</h2><p>${cases[15][4]}</p></div><div class="prompts">${['Where did my time go this week?','Show my open tasks','Help me plan tomorrow'].map(s=>`<button data-prompt="${s}">${s}${icon('next')}</button>`).join('')}</div></section></div><form class="composer" id="composer"><input aria-label="Message" placeholder="Ask about your time or tasks"><button aria-label="Send message" disabled>${icon('send')}</button></form>`}
function picker(){return `<div class="sheet-underlay">${header(cases[36])}<div class="toolbar"><span>All Tasks</span>${icon('filter')}</div>${tabs()}<div class="stage"><h3>New task</h3><p>Task Type · Unset</p></div></div><section class="sheet"><div class="handle"></div><div class="sheet-title"><h2>Task type</h2><button class="iconbutton" aria-label="Close Task type" data-action="back">${icon('close')}</button></div><label class="field-label" for="type-input">Search or create a Task Type</label><input class="field" id="type-input" placeholder="e.g. work/design" autocomplete="off"><div id="type-results">${stateBlock(36)}</div><button class="unset" data-action="unset"><span>Unset<small>No Task Type assigned</small></span>${icon('check')}</button></section><div class="home-line"></div>`}
function calendar(){return `<div class="body"><section class="cal-card"><h3>Google Calendar</h3><p class="support">Bring calendar commitments into your plan. Google events stay unchanged.</p><div class="account">${icon('check')}<div><h3>Connected</h3><p>alex.morgan@example.com</p></div></div>${stateBlock(28)}<p class="sync-state" id="sync-state">Last synced Oct 26, 10:42</p><div class="account-options"><button data-action="account">Account options</button></div></section></div>`}
function render(){const c=cases[current];document.body.className='variant-'+variant;let content='';
if(current===36)content=picker();
else {content=header(c);if(current===15)content+=conversation();else if(current===28)content+=calendar();else {let controls='';if([1,2,3].includes(current))controls=`<div class="toolbar"><button data-action="collections">${icon('task')}All Tasks${icon('down')}</button><button aria-label="Filter tasks" data-action="filters">${icon('filter')}</button></div>`+tabs();if([5,6].includes(current))controls=`<div class="toolbar"><button data-action="open">${icon('back')}Board</button><span>${current===5?'Archive':'Trash'}</span></div>`;if([7,8,12].includes(current))controls=week();if([9,10,11].includes(current))controls=recurrenceTabs();content+=`<div class="body ${current===8?'sheet-underlay':''}">${controls}${stateBlock(current===8?7:current)}${[10,11].includes(current)?`<div class="secondary-create">${button('New recurrence','routine',false)}</div>`:''}</div>`;if(current===8)content+=`<section class="sheet"><div class="handle"></div><div class="sheet-title"><h2>Add habit</h2><button class="iconbutton" aria-label="Close Add habit" data-action="back">${icon('close')}</button></div>${stateBlock(8)}</section>`;}if(current!==8)content+=dock();else content+='<div class="home-line"></div>';}
document.querySelector('#screen').innerHTML=`<div class="status"><span>12:30</span><div class="status-icons">${icon('wifi')}${icon('bars')}${icon('battery')}</div></div>`+content;
const field=document.querySelector('#type-input');if(field)field.addEventListener('input',()=>{const q=field.value.trim();document.querySelector('#type-results').innerHTML=q?`<div class="result"><button data-create-type="${esc(q)}">${icon('plus')} Create ${esc(q)}</button><p class="support">This will create a reusable Task Type.</p></div>`:stateBlock(36);report(q?'Typing a new Task Type':'Empty type library')});
const composer=document.querySelector('#composer');if(composer){const input=composer.querySelector('input'),send=composer.querySelector('button');input.addEventListener('input',()=>{send.disabled=!input.value.trim();send.classList.toggle('ready',!send.disabled)});composer.addEventListener('submit',e=>{e.preventDefault();showNotice('Message ready',`“${input.value}”`, 'This prototype does not call the Assistant or send messages.');report('Example message prepared')})}report();}
function showNotice(title,body,note='Prototype only · no changes are saved.'){document.querySelector('#overlay').innerHTML=`<section class="demo-sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h2>${esc(title)}</h2><p>${esc(body)}</p><button class="primary" data-action="dismiss">Done</button><p class="demo-note">${esc(note)}</p></section>`;document.querySelector('#overlay button').focus()}
function draft(kind){const name={task:'New task',routine:'New recurrence',goal:'Add Time Goal'}[kind],hint={task:'What needs doing?',routine:'Name your routine',goal:'Task Type, e.g. study'}[kind];document.querySelector('#overlay').innerHTML=`<form class="demo-sheet" id="draft" role="dialog" aria-modal="true" aria-label="${name}"><h2>${name}</h2><p>${kind==='routine'?'Create a routine, then choose whether to track it as a habit.':kind==='goal'?'Choose what to measure and how much time to aim for.':'Give your next step a name.'}</p><label class="field-label" for="draft-title">${kind==='goal'?'Task Type':'Name'}</label><input id="draft-title" class="field" required placeholder="${hint}">${kind==='goal'?'<label class="field-label" for="target">Weekly target (minutes)</label><input id="target" class="field" type="number" min="1" value="60">':''}<div class="actions"><button type="button" data-action="dismiss">Cancel</button><button class="primary">Preview ${kind==='goal'?'goal':kind}</button></div><p class="demo-note">Proposed handoff · local prototype only. No data is saved.</p></form>`;document.querySelector('#draft').onsubmit=e=>{e.preventDefault();const value=document.querySelector('#draft-title').value;showNotice('Draft preview',value);report(name+' draft preview')};document.querySelector('#draft-title').focus();report(name+' opened')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.case){current=Number(b.dataset.case);render();report('Changed tab');return}if(b.dataset.prompt){const input=document.querySelector('#composer input');input.value=b.dataset.prompt;input.dispatchEvent(new Event('input'));input.focus();report('Example prompt inserted; not sent');return}if(b.dataset.createType){showNotice('Task Type preview',b.dataset.createType);report('New Task Type preview');return}const a=b.dataset.action;if(['task','routine','goal'].includes(a))draft(a);else if(['open','board'].includes(a)){current=1;render();report('Open tasks')}else if(a==='active'){current=9;render();report('Active series')}else if(a==='dismiss'){document.querySelector('#overlay').innerHTML='';report('Returned to empty state')}else if(a==='reset'){current=initial;render()}else if(a==='back'){if(current===8){current=7;render()}else showNotice('Back navigation','In the app, this returns to the previous screen.')}else if(a==='help'){document.querySelector('#goal-help').innerHTML='<p class="goal-help">Progress includes Actual Blocks for this Task Type and its descendants. Completing a task does not add time.</p>';report('Goal help expanded')}else if(a==='sync'){document.querySelector('#sync-state').textContent='Checked just now · no calendars found';report('Simulated sync complete; still empty')}else if(a==='historical')showNotice('No habits were active this week','Historical empty weeks retain their date grid and a quiet message. First-use guidance is reserved for an empty habit library.');else if(a==='unset'){showNotice('Task Type: Unset','The task has no Task Type assigned.');report('Unset selected')}else if(a==='collections'){document.querySelector('#overlay').innerHTML='<section class="demo-sheet"><h2>Collections</h2>'+[[1,'Board'],[5,'Archive'],[6,'Trash']].map(([id,label])=>`<button class="field" data-action="dismiss" data-collection="${id}">${label}</button>`).join('')+'</section>'}else if(a)showNotice(a==='day'?'Day excluded':'Existing control',a==='day'?'Day is outside this prototype.':'This comparison focuses on empty states; this control keeps its existing app behavior.');if(b.dataset.collection){document.querySelector('#overlay').innerHTML='';current=Number(b.dataset.collection);render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('#overlay').innerHTML=''});
render();
